import React, { useEffect, useState } from 'react';
import api from '../services/api';

interface Advisory {
  advisory: string;
  synopsis: string;
  severity: string;
  products: string;
  publishDate: string;
  cves: string[];
  link: string;
}

const PAGE_SIZE = 10;

const PatchMgmt: React.FC = () => {
  const [advisories, setAdvisories] = useState<Advisory[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [severityFilter, setSeverityFilter] = useState<string>('All');
  const [sortBy, setSortBy] = useState<'publishDate' | 'severity'>('publishDate');
  const [sortOrder, setSortOrder] = useState<'asc' | 'desc'>('desc');
  const [page, setPage] = useState(1);

  useEffect(() => {
    setLoading(true);
    setError(null);
    api.get('/patches/redhat')
      .then(res => setAdvisories(res.data))
      .catch(() => setError('Failed to load advisories'))
      .finally(() => setLoading(false));
  }, []);

  // Filtering
  const filtered = severityFilter === 'All'
    ? advisories
    : advisories.filter(a => a.severity === severityFilter);

  // Sorting
  const sorted = [...filtered].sort((a, b) => {
    if (sortBy === 'publishDate') {
      const dateA = new Date(a.publishDate).getTime();
      const dateB = new Date(b.publishDate).getTime();
      return sortOrder === 'asc' ? dateA - dateB : dateB - dateA;
    } else if (sortBy === 'severity') {
      const sevOrder = ['Critical', 'Important', 'Moderate', 'Low', 'Unknown'];
      const idxA = sevOrder.indexOf(a.severity);
      const idxB = sevOrder.indexOf(b.severity);
      return sortOrder === 'asc' ? idxA - idxB : idxB - idxA;
    }
    return 0;
  });

  // Pagination
  const totalPages = Math.ceil(sorted.length / PAGE_SIZE);
  const paginated = sorted.slice((page - 1) * PAGE_SIZE, page * PAGE_SIZE);

  // Unique severities for filter dropdown
  const severities = Array.from(new Set(advisories.map(a => a.severity))).filter(Boolean);

  // Handle sorting
  const handleSort = (col: 'publishDate' | 'severity') => {
    if (sortBy === col) {
      setSortOrder(sortOrder === 'asc' ? 'desc' : 'asc');
    } else {
      setSortBy(col);
      setSortOrder('desc');
    }
  };

  // Handle page change
  const handlePageChange = (newPage: number) => {
    if (newPage >= 1 && newPage <= totalPages) setPage(newPage);
  };

  // Reset to page 1 when filter or sort changes
  useEffect(() => { setPage(1); }, [severityFilter, sortBy, sortOrder]);

  return (
    <div style={{ margin: '2rem 0' }}>
      <h2>RHEL Security Advisories</h2>
      <div style={{ margin: '1rem 0' }}>
        <label>Filter by Severity: </label>
        <select value={severityFilter} onChange={e => setSeverityFilter(e.target.value)}>
          <option value="All">All</option>
          {severities.map(s => (
            <option key={s} value={s}>{s}</option>
          ))}
        </select>
      </div>
      {loading && <div>Loading advisories...</div>}
      {error && <div style={{ color: 'red' }}>{error}</div>}
      {!loading && !error && (
        <>
          <div style={{ overflowX: 'auto', marginTop: '2rem' }}>
            <table style={{ borderCollapse: 'collapse', width: '100%' }}>
              <thead>
                <tr>
                  <th style={{ padding: '8px', borderBottom: '1px solid #ccc' }}>Advisory</th>
                  <th style={{ padding: '8px', borderBottom: '1px solid #ccc' }}>Synopsis</th>
                  <th style={{ padding: '8px', borderBottom: '1px solid #ccc', cursor: 'pointer' }} onClick={() => handleSort('severity')}>
                    Severity {sortBy === 'severity' ? (sortOrder === 'asc' ? '▲' : '▼') : ''}
                  </th>
                  <th style={{ padding: '8px', borderBottom: '1px solid #ccc' }}>Products</th>
                  <th style={{ padding: '8px', borderBottom: '1px solid #ccc', cursor: 'pointer' }} onClick={() => handleSort('publishDate')}>
                    Publish Date {sortBy === 'publishDate' ? (sortOrder === 'asc' ? '▲' : '▼') : ''}
                  </th>
                  <th style={{ padding: '8px', borderBottom: '1px solid #ccc' }}>CVEs</th>
                  <th style={{ padding: '8px', borderBottom: '1px solid #ccc' }}>Link</th>
                </tr>
              </thead>
              <tbody>
                {paginated.map(adv => (
                  <tr key={adv.advisory}>
                    <td style={{ padding: '8px', borderBottom: '1px solid #eee' }}>{adv.advisory}</td>
                    <td style={{ padding: '8px', borderBottom: '1px solid #eee' }}>{adv.synopsis}</td>
                    <td style={{ padding: '8px', borderBottom: '1px solid #eee' }}>{adv.severity}</td>
                    <td style={{ padding: '8px', borderBottom: '1px solid #eee' }}>{adv.products}</td>
                    <td style={{ padding: '8px', borderBottom: '1px solid #eee' }}>{adv.publishDate}</td>
                    <td style={{ padding: '8px', borderBottom: '1px solid #eee' }}>{adv.cves && adv.cves.length > 0 ? adv.cves.join(', ') : '-'}</td>
                    <td style={{ padding: '8px', borderBottom: '1px solid #eee' }}>
                      <a href={adv.link} target="_blank" rel="noopener noreferrer">View</a>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
          {/* Pagination Controls */}
          <div style={{ marginTop: '1rem', display: 'flex', justifyContent: 'center', alignItems: 'center', gap: '1rem' }}>
            <button onClick={() => handlePageChange(page - 1)} disabled={page === 1}>&lt; Prev</button>
            <span>Page {page} of {totalPages}</span>
            <button onClick={() => handlePageChange(page + 1)} disabled={page === totalPages}>Next &gt;</button>
          </div>
        </>
      )}
    </div>
  );
};

export default PatchMgmt;
